fn the_whole_table() {
    assert_eq!(next(State::Idle, Event::Start), Some(State::Running));
    assert_eq!(next(State::Running, Event::Pause), Some(State::Paused));
    assert_eq!(next(State::Running, Event::Finish), Some(State::Done));
    assert_eq!(next(State::Paused, Event::Start), Some(State::Running));
    assert_eq!(next(State::Paused, Event::Cancel), Some(State::Done));
    assert_eq!(next(State::Idle, Event::Cancel), Some(State::Done));
