    assert_eq!(next(State::Idle, Event::Finish), None);
    assert_eq!(next(State::Running, Event::Start), None);
    assert_eq!(next(State::Paused, Event::Pause), None);
    assert_eq!(next(State::Paused, Event::Finish), None);
    for event in [Event::Start, Event::Pause, Event::Finish, Event::Cancel] {
        assert_eq!(next(State::Done, event), None, "Done accepted {event:?}");
    }
}

