use crate::stage;

/// Runs the stages in order.
pub fn process(values: &[i64]) -> Vec<i64> {
    values
        .iter()
        .map(|v| {
            let v = stage::clean::run(*v);
            let v = stage::amplify::run(v);
            let v = stage::adjust::run(v);
            let v = stage::reduce::run(v);
            stage::shape::run(v)
        })
        .collect()
}

