/// Every contiguous run of three values, in order.
pub fn of_three(values: &[i64]) -> Vec<Vec<i64>> {
    let mut out = Vec::new();
    if values.len() < 3 {
        return out;
    }
    // Off by one: the final window never gets built.
    for start in 0..(values.len() - 3) {
        out.push(values[start..start + 3].to_vec());
    }
    out
}

