use std::cell::Cell;

thread_local! {
    static COMPARISONS: Cell<u64> = const { Cell::new(0) };
}

/// Counts one comparison. The measurement is the count, not the clock: a
/// wall-clock bound on a shared machine is a flaky verifier.
pub fn note_comparison() {
    COMPARISONS.with(|c| c.set(c.get() + 1));
}

pub fn comparisons() -> u64 {
    COMPARISONS.with(Cell::get)
}

pub fn reset() {
    COMPARISONS.with(|c| c.set(0));
}

