use crate::instrument::note_comparison;

pub fn first_duplicate(values: &[i64]) -> Option<i64> {
    for i in 0..values.len() {
        for j in 0..i {
            note_comparison();
            if values[i] == values[j] {
                return Some(values[i]);
            }
        }
    }
    None
}

