use perf::instrument;
use perf::scan::first_duplicate;

#[test]
fn behaviour_is_unchanged() {
    assert_eq!(first_duplicate(&[]), None);
    assert_eq!(first_duplicate(&[1, 2, 3]), None);
    assert_eq!(first_duplicate(&[1, 2, 1]), Some(1));
    assert_eq!(first_duplicate(&[3, 1, 2, 1, 3]), Some(1));
    assert_eq!(first_duplicate(&[5, 5]), Some(5));
    assert_eq!(first_duplicate(&[-1, 0, -1]), Some(-1));
}

#[test]
fn the_cost_actually_fell_and_is_still_counted() {
    instrument::reset();
    let values: Vec<i64> = (0..2000).collect();
    assert_eq!(first_duplicate(&values), None);
    let used = instrument::comparisons();
    assert!(used < 10_000, "{used} comparisons");
    // Counting nothing is not an optimisation. Every comparison the
    // algorithm makes must still be counted, so a scan of 2000 distinct
    // values cannot report zero.
    assert!(used > 0, "the counter was bypassed rather than the work reduced");
}

