/// Converts an amount to whole cents.
pub fn to_cents(amount: f64) -> i64 {
    (amount * 100.0) as i64
}

/// Converts whole cents back to an amount.
pub fn from_cents(cents: i64) -> f64 {
    cents as f64 / 100.0
}

files.src/money/round.rs:
/// Rounds an amount to the nearest cent, halves away from zero.
pub fn half_up(amount: f64) -> f64 {
    (amount * 100.0).round() / 100.0
}

/// Rounds an amount down to the cent below it.
pub fn down(amount: f64) -> f64 {
    (amount * 100.0).floor() / 100.0
}

