files.src/rollup/daily.rs:
use crate::money::convert;

/// Totals the entries of one day, in the stored minor unit.
pub fn totals(day: &str, entries: &[(&str, f64)]) -> i64 {
    entries
        .iter()
        .filter(|(on, _)| *on == day)
        .map(|(_, amount)| convert::to_minor(*amount))
        .sum()
}

files.src/rollup/weekly.rs:
use crate::rollup::daily;

/// Totals every day given, in cents.
pub fn totals(days: &[&str], entries: &[(&str, f64)]) -> i64 {
    days.iter().map(|day| daily::totals(day, entries)).sum()
}

files.src/rollup/monthly.rs:
use crate::rollup::weekly;

/// Totals the weeks of a month, in cents.
pub fn totals(weeks: &[Vec<&str>], entries: &[(&str, f64)]) -> i64 {
    weeks.iter().map(|week| weekly::totals(week, entries)).sum()
}

files.src/report.rs:
use crate::money::format;
use crate::rollup::daily;

/// One line of the report: the day and what it came to.
pub fn daily_line(day: &str, entries: &[(&str, f64)]) -> String {
    format!("{}  {}", day, format::cents(daily::totals(day, entries)))
}

